// include/constants_param_wizard.php, row 455
"specifies returned information: <br> - <i>html</i> - (default) - returns image size as HTML attributes (height='xxx' width='yyy')<br> - <i>width</i> - returns width of image in pixels<br> - <i>height</i> - returns height of image in pixels<br> - <i>imgtype</i> - returns flag indicating the type of the image: 1 = GIF, 2 = JPG, 3 = PNG, 4 = SWF, 5 = PSD, 6 = BMP, 7 = TIFF(intel byte order), 8 = TIFF(motorola byte order), 9 = JPC, 10 = JP2, 11 = JPX, 12 = JB2, 13 = SWC, 14 = IFF, 15 = WBMP, 16 = XBM<br> - <i>mime</i> - returns mimetype of the image (like 'image/gif', 'application/x-shockwave-flash', ...)" => "\xEE\xEF\xF0\xE5\xE4\xE5\xEB\xFF \xE2\xFA\xF0\xED\xE0\xF2\xE0\xF2\xE0 \xE8\xED\xF4\xEE\xF0\xEC\xE0\xF6\xE8\xFF: <br> - <i>html</i> - (\xEF\xEE \xEF\xEE\xE4\xF0\xE0\xE7\xE1\xE8\xF0\xE0\xED\xE5) - \xE2\xF0\xFA\xF9\xE0 \xF0\xE0\xE7\xEC\xE5\xF0\xE0 \xED\xE0 \xE8\xE7\xEE\xE1\xF0\xE0\xE6\xE5\xED\xE8\xE5\xF2\xEE \xEA\xE0\xF2\xEE HTML \xE0\xF2\xF0\xE8\xE1\xF3\xF2\xE8 (height='xxx' width='yyy')<br> - <i>width</i> - \xE2\xF0\xFA\xF9\xE0 \xF8\xE8\xF0\xE8\xED\xE0\xF2\xE0 \xED\xE0 \xE8\xE7\xEE\xE1\xF0\xE0\xE6\xE5\xED\xE8\xE5\xF2\xEE \xE2 \xEF\xE8\xEA\xF1\xE5\xEB\xE8<br> - <i>height</i> - \xE2\xF0\xFA\xF9\xE0 \xE2\xE8\xF1\xEE\xF7\xE8\xED\xE0\xF2\xE0 \xED\xE0 \xE8\xE7\xEE\xE1\xF0\xE0\xE6\xE5\xED\xE8\xE5\xF2\xEE \xE2 \xEF\xE8\xEA\xF1\xE5\xEB\xE8<br> - <i>imgtype</i> - \xE2\xF0\xFA\xF9\xE0 \xF4\xEB\xE0\xE3, \xF3\xEA\xE0\xE7\xE2\xE0\xF9 \xF2\xE8\xEF\xE0 \xED\xE0 \xE8\xE7\xEE\xE1\xF0\xE0\xE6\xE5\xED\xE8\xE5\xF2\xEE: 1 = GIF, 2 = JPG, 3 = PNG, 4 = SWF, 5 = PSD, 6 = BMP, 7 = TIFF(intel byte order), 8 = TIFF(motorola byte order), 9 = JPC, 10 = JP2, 11 = JPX, 12 = JB2, 13 = SWC, 14 = IFF, 15 = WBMP, 16 = XBM<br> - <i>mime</i> - \xE2\xF0\xFA\xF9\xE0 mimetype \xED\xE0 \xE8\xE7\xEE\xE1\xF0\xE0\xE6\xE5\xED\xE8\xE5\xF2\xEE (\xED\xE0\xEF\xF0. 'image/gif', 'application/x-shockwave-flash', ...)", // ai 2026-06

